import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

function App() {
  // ===== STATE =====
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [errorDetails, setErrorDetails] = useState('');
  const [smsConversation, setSmsConversation] = useState([]);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [serverStatus, setServerStatus] = useState('checking');
  const [activationDone, setActivationDone] = useState(false);
  const [showRegistrationComplete, setShowRegistrationComplete] = useState(false);
  const [myPhone, setMyPhone] = useState('0712345678');

  // ===== DASHBOARD STATE =====
  const [allMatches, setAllMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [myMatches, setMyMatches] = useState([]);
  const [chatMessages, setChatMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeChatUser, setActiveChatUser] = useState(null);
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [selectedUser, setSelectedUser] = useState(null);
  const [isSendingMessage, setIsSendingMessage] = useState(false);

  // ============================================
  // SAMPLE DATA
  // ============================================

  const SAMPLE_MATCHES = [
    { id: 1, phone: '0722010203', name: 'Lina Moraa', age: 29, town: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
    { id: 2, phone: '0701223344', name: 'Dorine Gakii', age: 26, town: 'Nakuru', profession: 'Teacher', education: 'Diploma', religion: 'Christian', ethnicity: 'Kamba', description: 'Caring and dedicated. Loves children and education.' },
    { id: 3, phone: '0700112233', name: 'Aisha Bahati', age: 27, town: 'Mombasa', profession: 'Accountant', education: 'Graduate', religion: 'Muslim', ethnicity: 'Swahili', description: 'Ambitious and hardworking.' }
  ];

  const SAMPLE_REQUESTS = [
    { id: 101, phone: '0723000001', name: 'Michael Ochieng', age: 30, town: 'Nairobi', message: '💕 Shows interest in you', status: 'pending' }
  ];

  const SAMPLE_MY_MATCHES = [
    { id: 201, phone: '0724000001', name: 'Grace Akinyi', age: 27, town: 'Kisumu', status: 'accepted' },
    { id: 202, phone: '0724000002', name: 'Peter Mwangi', age: 29, town: 'Nakuru', status: 'accepted' }
  ];

  // ============================================
  // STEPS
  // ============================================

  const STEPS = [
    {
      id: 1,
      title: 'Activate Service',
      subtitle: 'Send PENZI to activate',
      icon: '💑',
      fields: [{ key: 'penzi', label: 'Enter Activation Code', placeholder: 'Type PENZI', type: 'text' }],
      isActivation: true
    },
    {
      id: 2,
      title: 'Service Registration',
      subtitle: 'Create your account',
      icon: '📝',
      fields: [
        { key: 'phone_number', label: '📱 Phone Number', placeholder: '0712345678', type: 'tel' },
        { key: 'name', label: '👤 Full Name', placeholder: 'John Doe', type: 'text' },
        { key: 'age', label: '🎂 Age', placeholder: '26', type: 'number' },
        { key: 'gender', label: '⚤ Gender', type: 'select', options: ['Male', 'Female', 'Other'] },
        { key: 'county', label: '📍 County', placeholder: 'Nakuru', type: 'text' },
        { key: 'town', label: '🏙️ Town/City', placeholder: 'Naivasha', type: 'text' }
      ],
      isRegistration: true,
      userMessage: (data) => `start#${data.name}#${data.age}#${data.gender}#${data.county}#${data.town}`
    },
    {
      id: 3,
      title: 'Details Registration',
      subtitle: 'Complete your profile',
      icon: '📋',
      fields: [
        { key: 'education_level', label: '🎓 Education Level', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'] },
        { key: 'profession', label: '💼 Profession', placeholder: 'Accountant', type: 'text' },
        { key: 'marital_status', label: '💍 Marital Status', type: 'select', options: ['single', 'married', 'divorced', 'widowed', 'separated'] },
        { key: 'religion', label: '⛪ Religion', placeholder: 'Christian', type: 'text' },
        { key: 'ethnicity', label: '🌍 Ethnicity', placeholder: 'Kikuyu', type: 'text' }
      ],
      isDetails: true,
      userMessage: (data) => `details#${data.education_level}#${data.profession}#${data.marital_status}#${data.religion}#${data.ethnicity}`
    },
    {
      id: 4,
      title: 'Self-Description',
      subtitle: 'Tell us about yourself',
      icon: '💭',
      fields: [{ key: 'description', label: 'Describe yourself', placeholder: 'Hardworking, honest, family-oriented...', type: 'textarea' }],
      isSelfDescription: true,
      userMessage: (data) => `MYSELF ${data.description}`
    },
    {
      id: 5,
      title: 'Matching Request',
      subtitle: 'Search for your match',
      icon: '❤️',
      fields: [
        { key: 'age_range', label: '📅 Age Range', placeholder: '26-30', type: 'text' },
        { key: 'town', label: '📍 Town/City', placeholder: 'Nairobi', type: 'text' }
      ],
      isMatching: true,
      userMessage: (data) => `match#${data.age_range}#${data.town}`
    }
  ];

  // ============================================
  // API CALLS
  // ============================================

  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = { method, headers: { 'Content-Type': 'application/json' } };
      if (body) options.body = JSON.stringify(body);
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      return await response.json();
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE
  // ============================================

  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);
        setCurrentStep(parsed.currentStep || 0);
        setCompletedSteps(new Set(parsed.completedSteps || []));
        setSmsConversation(parsed.smsConversation || []);
        setActivationDone(parsed.activationDone || false);
        setAllMatches(parsed.allMatches || SAMPLE_MATCHES);
        setIncomingRequests(parsed.incomingRequests || SAMPLE_REQUESTS);
        setMyMatches(parsed.myMatches || SAMPLE_MY_MATCHES);
        setChatMessages(parsed.chatMessages || []);
        setActiveTab(parsed.activeTab || 'discover');
        if (parsed.currentUser) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================

  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        smsConversation,
        currentUser,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatMessages,
        activeTab
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, smsConversation, currentUser, activationDone, allMatches, incomingRequests, myMatches, chatMessages, activeTab]);

  // ============================================
  // CHECK SERVER
  // ============================================

  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPERS
  // ============================================

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / STEPS.length) * 100);
  };

  const goToStep = (index) => {
    if (index >= 0 && index < STEPS.length) {
      setCurrentStep(index);
    }
  };

  const buildSmsPreview = (step) => {
    if (step.id === 1) return 'PENZI';
    if (step.id === 2) {
      return `start#${formData.name || 'John Doe'}#${formData.age || '26'}#${formData.gender || 'Male'}#${formData.county || 'Nakuru'}#${formData.town || 'Naivasha'}`;
    }
    if (step.id === 3) {
      return `details#${formData.education_level || 'diploma'}#${formData.profession || 'driver'}#${formData.marital_status || 'single'}#${formData.religion || 'christian'}#${formData.ethnicity || 'mijikenda'}`;
    }
    if (step.id === 4) {
      return `MYSELF ${formData.description || 'Your description here'}`;
    }
    if (step.id === 5) {
      return `match#${formData.age_range || '26-30'}#${formData.town || 'Nairobi'}`;
    }
    return '';
  };

  // ============================================
  // LOGOUT / EXIT
  // ============================================

  const handleLogout = () => {
    localStorage.removeItem('penziState');
    setIsLoggedIn(false);
    setCurrentUser(null);
    setAllMatches([]);
    setIncomingRequests([]);
    setMyMatches([]);
    setChatMessages([]);
    setActiveChatUser(null);
    setSmsConversation([]);
    setActivationDone(false);
    setShowRegistrationComplete(false);
    setCurrentStep(0);
    setCompletedSteps(new Set());
    addNotification('👋 Logged out successfully!');
  };

  // ============================================
  // PROFILE VIEW FUNCTION
  // ============================================

  const viewProfile = (user) => {
    setSelectedUser(user);
    setShowProfile(true);
  };

  // ============================================
  // DASHBOARD FUNCTIONS
  // ============================================

  const handleExpressInterest = async (targetPhone) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/send-interest`, 'POST', { target_phone: targetPhone });
      if (result && result.success) {
        addToConversation('📱 You', 'Expressing interest', false);
        addToConversation('🤖 System', '💕 Interest sent!', true);
        setAllMatches(prev => prev.filter(m => m.phone !== targetPhone));
        addNotification('💕 Interest sent successfully!');
      } else {
        addNotification('❌ Could not send interest.', 'error');
      }
    } catch (error) {
      addNotification('❌ Error expressing interest.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAcceptRequest = async (request) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/respond-to-request`, 'POST', { user_phone: request.phone, action: "accept" });
      if (result && result.success) {
        const newMatch = { id: Date.now(), phone: request.phone, name: request.name, age: request.age, town: request.town, status: 'accepted' };
        setMyMatches(prev => [...prev, newMatch]);
        setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
        addNotification(`✅ You accepted ${request.name}'s request!`);
        addToConversation('📱 You', `Accepted ${request.name}`, false);
        addToConversation('🤖 System', `✅ Matched with ${request.name}!`, true);
      } else {
        addNotification('❌ Could not accept request.', 'error');
      }
    } catch (error) {
      addNotification('❌ Error accepting request.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRejectRequest = async (request) => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/respond-to-request`, 'POST', { user_phone: request.phone, action: "reject", reason: "Not interested" });
      if (result && result.success) {
        setIncomingRequests(prev => prev.filter(r => r.id !== request.id));
        addNotification(`❌ You declined ${request.name}'s request.`);
      } else {
        addNotification('❌ Could not decline request.', 'error');
      }
    } catch (error) {
      addNotification('❌ Error declining request.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  const loadMatches = async () => {
    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const result = await callApi(`/${phone}/matches?age_range=20-40&town=Nairobi`, 'GET');
      if (result && result.status === 'success') {
        const matchesData = result.data?.matches || result.matches || [];
        setAllMatches(matchesData);
        addNotification(`✅ Found ${matchesData.length} matches!`);
      } else {
        setAllMatches(SAMPLE_MATCHES);
      }
    } catch (error) {
      setAllMatches(SAMPLE_MATCHES);
    } finally {
      setIsLoading(false);
    }
  };

  const startChat = (match) => {
    setActiveChatUser(match);
    setActiveTab('chat');
    addNotification(`💬 Chat started with ${match.name}`);
  };

  const sendMessage = () => {
    if (!newMessage.trim() || !activeChatUser) return;
    const newMsg = {
      id: Date.now(),
      sender: 'You',
      message: newMessage,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isMine: true,
      status: 'sending'
    };
    setChatMessages(prev => [...prev, newMsg]);
    setIsSendingMessage(true);
    setNewMessage('');
    setTimeout(() => {
      setChatMessages(prev => prev.map(msg => msg.id === newMsg.id ? { ...msg, status: 'sent' } : msg));
      setIsSendingMessage(false);
      addNotification(`📤 Message sent to ${activeChatUser.name}`);
    }, 800);
  };

  // ============================================
  // EXECUTE API (Registration Flow)
  // ============================================

  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      let phone = formData.phone_number || myPhone || '0712345678';

      if (step.isActivation) {
        const result = await callApi('/activate', 'POST', { penzi: formData.penzi || 'penzi' });
        if (result && result.status === 'success') {
          const welcomeMsg = result.message || 'Welcome to our dating service!';
          addToConversation('📱 You', 'PENZI', false);
          addToConversation('🤖 System', welcomeMsg, true);
          setActivationDone(true);
          setResponseMessage('✅ Service activated!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Service activated!');
        } else {
          setResponseMessage('❌ Activation failed.');
          setIsSuccess(false);
        }
      } else if (step.isRegistration) {
        const data = { phone_number: formData.phone_number, name: formData.name, age: formData.age, gender: formData.gender, county: formData.county, town: formData.town };
        const result = await callApi('/register', 'POST', data);
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || `Profile created for ${formData.name}`;
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setMyPhone(formData.phone_number || '0712345678');
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
        } else {
          setResponseMessage('❌ Registration failed.');
          setIsSuccess(false);
        }
      } else if (step.isDetails) {
        const data = { education_level: formData.education_level, profession: formData.profession, marital_status: formData.marital_status, religion: formData.religion, ethnicity: formData.ethnicity };
        const result = await callApi(`/${phone}/complete-profile`, 'POST', data);
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || 'Profile completed!';
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Profile completed!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed!');
        } else {
          setResponseMessage('❌ Profile completion failed.');
          setIsSuccess(false);
        }
      } else if (step.isSelfDescription) {
        const result = await callApi(`/${phone}/self-description`, 'POST', { description: formData.description });
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || 'Self-description added!';
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Self-description added!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
        } else {
          setResponseMessage('❌ Self-description failed.');
          setIsSuccess(false);
        }
      } else if (step.isMatching) {
        const message = `match#${formData.age_range}#${formData.town}`;
        const result = await callApi('/sms', 'POST', { phone_number: phone, message: message });
        const userMsg = step.userMessage(formData);
        addToConversation('📱 You', userMsg, false);
        if (result && result.matches) {
          const matchesData = result.matches;
          setAllMatches(matchesData);
          addToConversation('🤖 System', `Found ${matchesData.length} matches!`, true);
          setResponseMessage(`✅ Found ${matchesData.length} matches!`);
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          const user = { phone: formData.phone_number || phone || '0712345678', name: formData.name || 'User' };
          setCurrentUser(user);
          setShowRegistrationComplete(true);
          setTimeout(() => {
            setIsLoggedIn(true);
            addNotification(`🎉 Welcome to PENZI!`);
          }, 1500);
        } else {
          setResponseMessage('❌ No matches found.');
          setIsSuccess(false);
        }
      }
    } catch (error) {
      setResponseMessage('❌ Network error.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // RENDER SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;
    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION
  // ============================================

  const renderRegistration = () => {
    const step = STEPS[currentStep];
    const isFirstStep = currentStep === 0;
    const isLastStep = currentStep === STEPS.length - 1;
    const previewSms = buildSmsPreview(step);
    const isActivationStep = step.id === 1;

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="top-actions">
            <button className="btn-top btn-exit-top" onClick={handleLogout}>🚪 Exit</button>
          </div>
          <div className="registration-header">
            <div className="registration-icon">{step.icon}</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>
          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">{serverStatus === 'connected' ? '✅ Server Connected' : '⏳ Checking...'}</span>
          </div>
          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar"><div className="progress-fill" style={{ width: `${getProgress()}%` }}></div></div>
              <span className="progress-text">{getProgress()}% Complete</span>
            </div>
          )}
          {renderSmsConversation()}
          <div className="step-info-card">
            <div className="step-number">{isActivationStep ? '🔑 ENTRY POINT' : `Step ${currentStep + 1}`}</div>
            <h2>{step.title}</h2>
            <p>{step.subtitle}</p>
          </div>
          <form onSubmit={(e) => { e.preventDefault(); executeApi(); }} className="registration-form">
            {isActivationStep && (
              <div className="activation-hint">
                <div className="hint-bubble">
                  <span className="hint-label">📱 To activate:</span>
                  <span className="hint-code">PENZI</span>
                </div>
              </div>
            )}
            {step.fields && step.fields.map((field) => (
              <div key={field.key} className="input-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select value={formData[field.key] || ''} onChange={(e) => handleInputChange(field.key, e.target.value)} className="input-field" required>
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (<option key={opt} value={opt}>{opt}</option>))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea value={formData[field.key] || ''} onChange={(e) => handleInputChange(field.key, e.target.value)} placeholder={field.placeholder} className="textarea-field" rows={3} required />
                ) : (
                  <input type={field.type || 'text'} value={formData[field.key] || ''} onChange={(e) => handleInputChange(field.key, e.target.value)} placeholder={field.placeholder} className="input-field" required />
                )}
              </div>
            ))}
            {previewSms && (<div className="sms-preview-container"><div className="sms-preview-label">📱 Your SMS:</div><div className="sms-preview-content">{previewSms}</div></div>)}
            <div className="registration-actions">
              <button type="button" onClick={() => goToStep(currentStep - 1)} disabled={currentStep === 0 || isLoading || !activationDone} className="btn-secondary">⬅ Previous</button>
              <button type="submit" disabled={isLoading || serverStatus === 'error'} className={`btn-primary ${isLoading ? 'loading' : ''}`}>{isLoading ? '⏳' : isActivationStep ? '💑 Activate' : '📤 Send'}</button>
              <button type="button" onClick={() => goToStep(currentStep + 1)} disabled={isLastStep || isLoading || !completedSteps.has(currentStep)} className="btn-secondary">Next ➡</button>
            </div>
          </form>
          {errorDetails && (<div className="error-details"><p className="error-detail-text">💡 {errorDetails}</p></div>)}
          {responseMessage && (<div className={`response-message ${isSuccess ? 'success' : 'error'}`}>{responseMessage}</div>)}
          {showRegistrationComplete && (
            <div className="registration-complete">
              <div className="complete-icon">🎉</div>
              <h2>Registration Complete!</h2>
              <p>Welcome {currentUser?.name}!</p>
              <button className="btn-primary" style={{ marginTop: '16px', width: '100%', padding: '14px' }} onClick={() => { setIsLoggedIn(true); loadMatches(); }}>Go to Dashboard →</button>
            </div>
          )}
          <div className="registration-footer"><p>🔒 Your data is safe</p></div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER NOTIFICATIONS
  // ============================================

  const renderNotifications = () => {
    if (notifications.length === 0) return null;
    return (
      <div className="notifications-container">
        {notifications.map((notif) => (<div key={notif.id} className={`notification ${notif.type || 'success'}`}>{notif.message}</div>))}
      </div>
    );
  };

  // ============================================
  // RENDER PROFILE MODAL
  // ============================================

  const renderProfileModal = () => {
    if (!selectedUser || !showProfile) return null;
    return (
      <div className="modal-overlay" onClick={() => { setShowProfile(false); setSelectedUser(null); }}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => { setShowProfile(false); setSelectedUser(null); }}>✕</button>
          <div className="profile-header">
            <div className="profile-avatar">{selectedUser.name?.charAt(0) || '?'}</div>
            <h2>{selectedUser.name}</h2>
            <p>{selectedUser.age || '?'} years • {selectedUser.town || 'Unknown'}</p>
          </div>
          <div className="profile-details">
            <div className="profile-item"><span className="label">📞 Phone</span><span>{selectedUser.phone}</span></div>
            <div className="profile-item"><span className="label">💼 Profession</span><span>{selectedUser.profession || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🎓 Education</span><span>{selectedUser.education || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💍 Marital Status</span><span>{selectedUser.marital_status || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🙏 Religion</span><span>{selectedUser.religion || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{selectedUser.ethnicity || 'Not specified'}</span></div>
            {selectedUser.description && (<div className="profile-item full-width"><span className="label">💭 About Me</span><span>{selectedUser.description}</span></div>)}
          </div>
          <div className="modal-actions">
            <button className="btn-secondary" onClick={() => { setShowProfile(false); setSelectedUser(null); }}>Close</button>
            <button className="btn-primary" onClick={() => { handleExpressInterest(selectedUser.phone); setShowProfile(false); setSelectedUser(null); }}>💕 Express Interest</button>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================

  const renderDashboard = () => {
    const currentMatch = allMatches[currentMatchIndex] || allMatches[0];
    const hasMatches = allMatches.length > 0;
    const hasRequests = incomingRequests.length > 0;
    const hasMyMatches = myMatches.length > 0;
    const hasChatMessages = chatMessages.length > 0;

    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left"><h1>💑 PENZI</h1><span className="live-badge">❤️ Live</span></div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="btn-exit" onClick={handleLogout} title="Logout">🚪</button>
          </div>
        </header>
        <nav className="dashboard-nav">
          <button className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} onClick={() => setActiveTab('discover')}>🔍 Discover <span className="nav-badge">{allMatches.length}</span></button>
          <button className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} onClick={() => setActiveTab('matches')}>💕 Matches <span className="nav-badge">{myMatches.length}</span></button>
          <button className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} onClick={() => setActiveTab('requests')}>📬 Requests {incomingRequests.length > 0 && <span className="nav-badge red">{incomingRequests.length}</span>}</button>
          <button className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} onClick={() => setActiveTab('chat')}>💬 Chat {hasChatMessages && <span className="nav-badge">{chatMessages.length}</span>}</button>
        </nav>
        <main className="dashboard-content">
          {activeTab === 'discover' && (
            <div className="discover-container">
              {hasMatches ? (
                <div className="match-card">
                  <div className="match-card-header">
                    <div className="match-avatar" onClick={() => viewProfile(currentMatch)}>{currentMatch?.name?.charAt(0) || '?'}</div>
                    <div className="match-info"><h3>{currentMatch?.name}</h3><p>{currentMatch?.age} years • {currentMatch?.town}</p></div>
                  </div>
                  <div className="match-details">
                    <div className="detail-item"><span className="detail-label">💼 Profession</span><span className="detail-value">{currentMatch?.profession || 'N/A'}</span></div>
                    <div className="detail-item"><span className="detail-label">🎓 Education</span><span className="detail-value">{currentMatch?.education || 'N/A'}</span></div>
                    <div className="detail-item"><span className="detail-label">🙏 Religion</span><span className="detail-value">{currentMatch?.religion || 'N/A'}</span></div>
                    <div className="detail-item"><span className="detail-label">🌍 Ethnicity</span><span className="detail-value">{currentMatch?.ethnicity || 'N/A'}</span></div>
                    {currentMatch?.description && (<div className="detail-item full-width"><span className="detail-label">💭 About Me</span><span className="detail-value description">{currentMatch.description}</span></div>)}
                  </div>
                  <div className="match-actions">
                    <button className="btn-secondary" onClick={() => viewProfile(currentMatch)}>👤 View Profile</button>
                    <button className="btn-primary" onClick={() => handleExpressInterest(currentMatch.phone)} disabled={isLoading}>{isLoading ? '⏳' : '💕 Interested'}</button>
                  </div>
                  <div className="match-navigation">
                    <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 1))} disabled={currentMatchIndex === 0}>⬅ Prev</button>
                    <span className="match-counter">{currentMatchIndex + 1}/{allMatches.length}</span>
                    <button className="nav-btn" onClick={() => setCurrentMatchIndex(Math.min(allMatches.length - 1, currentMatchIndex + 1))} disabled={currentMatchIndex === allMatches.length - 1}>Next ➡</button>
                  </div>
                </div>
              ) : (<div className="empty-state"><div className="empty-icon">🔍</div><h2>No Matches</h2><button className="btn-primary" onClick={loadMatches}>🔄 Refresh</button></div>)}
            </div>
          )}
          {activeTab === 'matches' && (
            <div className="matches-container">
              {hasMyMatches ? (
                <div className="matches-grid">
                  {myMatches.map((match) => (
                    <div key={match.id} className="match-item">
                      <div className="match-avatar" onClick={() => viewProfile(match)}>{match.name?.charAt(0) || '?'}</div>
                      <div className="match-info">
                        <h4 onClick={() => viewProfile(match)}>{match.name}</h4>
                        <p>{match.age} years • {match.town}</p>
                        <span className="match-status">✅ Accepted</span>
                      </div>
                      <button className="btn-chat" onClick={() => startChat(match)}>💬</button>
                    </div>
                  ))}
                </div>
              ) : (<div className="empty-state"><div className="empty-icon">💕</div><h2>No Matches</h2><button className="btn-primary" onClick={() => setActiveTab('discover')}>Discover</button></div>)}
            </div>
          )}
          {activeTab === 'requests' && (
            <div className="requests-container">
              {hasRequests ? (
                <div className="requests-list">
                  {incomingRequests.map((request) => (
                    <div key={request.id} className="request-item">
                      <div className="request-info">
                        <div className="request-avatar" onClick={() => viewProfile(request)}>{request.name?.charAt(0) || '?'}</div>
                        <div>
                          <h4 onClick={() => viewProfile(request)}>{request.name}</h4>
                          <p>{request.age} years • {request.town}</p>
                          <p className="request-message">💕 {request.message}</p>
                        </div>
                      </div>
                      <div className="request-actions">
                        <button className="btn-accept" onClick={() => handleAcceptRequest(request)} disabled={isLoading}>{isLoading ? '⏳' : '✅'}</button>
                        <button className="btn-decline" onClick={() => handleRejectRequest(request)} disabled={isLoading}>{isLoading ? '⏳' : '❌'}</button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (<div className="empty-state"><div className="empty-icon">📬</div><h2>No Requests</h2></div>)}
            </div>
          )}
          {activeTab === 'chat' && (
            <div className="chat-container">
              <div className="chat-header">
                <h3>💬 {activeChatUser ? `Chat with ${activeChatUser.name}` : 'Messages'}</h3>
                {activeChatUser && <button className="btn-close-chat" onClick={() => setActiveChatUser(null)}>✕</button>}
              </div>
              <div className="chat-messages">
                {chatMessages.length === 0 ? (
                  <div className="empty-state"><div className="empty-icon">💬</div><h3>No Messages</h3><button className="btn-primary" onClick={() => setActiveTab('matches')}>View Matches</button></div>
                ) : (
                  chatMessages.map((msg) => (
                    <div key={msg.id} className={`message ${msg.isMine ? 'sent' : 'received'}`}>
                      <p>{msg.message}</p>
                      <span className="message-time">{msg.time}</span>
                      {msg.isMine && msg.status === 'sending' && <span className="message-status">⏳ Sending...</span>}
                      {msg.isMine && msg.status === 'sent' && <span className="message-status">✓ Sent</span>}
                    </div>
                  ))
                )}
              </div>
              <div className="chat-input">
                <input type="text" value={newMessage} onChange={(e) => setNewMessage(e.target.value)} placeholder={activeChatUser ? `Message ${activeChatUser.name}...` : "Select a match..."} onKeyPress={(e) => { if (e.key === 'Enter') sendMessage(); }} disabled={!activeChatUser || isSendingMessage} />
                <button className="btn-send" onClick={sendMessage} disabled={!activeChatUser || !newMessage.trim() || isSendingMessage}>{isSendingMessage ? '⏳' : 'Send'}</button>
              </div>
              {!activeChatUser && chatMessages.length > 0 && (<div className="chat-select-hint"><p>💡 Select a match from Matches tab</p><button className="btn-secondary" onClick={() => setActiveTab('matches')}>Go to Matches</button></div>)}
            </div>
          )}
        </main>
        {showProfile && renderProfileModal()}
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================

  return (
    <div className="app">
      {renderNotifications()}
      {isLoggedIn ? renderDashboard() : renderRegistration()}
    </div>
  );
}

export default App;
